import { signal } from 'kerfjs';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret } from '@kerfjs/ui/token-search-field';

type Filter = { id: string; label: string };
export function createIssueSearch() {
  const tokens = signal<Filter[]>([{ id: 'status:open', label: 'Status: open' }]);
  const suggestions = signal<Filter[]>([]);
  const announce = signal('');
  const parse = (text: string) => { suggestions.value = text.startsWith('assignee:') ? [{ id: text, label: `Assignee: ${text.slice(9)}` }] : []; };
  const replaceTokens = (next: Filter[], message: string, field: HTMLElement) => { tokens.value = next; announce.value = message; queueMicrotask(() => placeTokenSearchCaret(field)); };
  const render = () => <section><TokenSearchField id="issue-search" label="Search issues" tokens={tokens.value} placeholder="Search issues or add a filter" action="issue-search" /><p class="sr-only" aria-live="polite">{announce.value}</p><ul aria-label="Search suggestions">{suggestions.value.map(token => <li><button type="button" data-action="accept-suggestion" data-token-id={token.id}>{token.label}</button></li>)}</ul></section>;
  return { render, input(field: HTMLElement) { parse(readTokenSearchField(field).text); }, action(command: string, element: HTMLElement) { const field = document.getElementById('issue-search'); if (!field) return; if (command === 'clear-search') { field.textContent = ''; suggestions.value = []; announce.value = 'Search cleared'; placeTokenSearchCaret(field); } if (command === 'remove-token' && element.dataset.tokenId) replaceTokens(tokens.value.filter(token => token.id !== element.dataset.tokenId), `Removed ${element.dataset.tokenId}`, field); if (command === 'accept-suggestion' && element.dataset.tokenId) { const token = suggestions.value.find(item => item.id === element.dataset.tokenId); if (token) replaceTokens([...tokens.value, token], `Added ${token.label} filter`, field); } } };
}
